/// C runtime for std.process — process execution (exec, exec_output).
pub const PROCESS_RUNTIME: &str = r#"
// ── std.process runtime ──────────────────────────────────────
static inline int64_t gorget_exec(const char* cmd) {
    int status = system(cmd);
    if (status == -1) return -1;
    #ifdef _WIN32
    return (int64_t)status;
    #else
    return WIFEXITED(status) ? (int64_t)WEXITSTATUS(status) : (int64_t)-1;
    #endif
}

typedef struct ExecResult {
    Str output;
    Str errors;
    int64_t exit_code;
} ExecResult;

static inline ExecResult gorget_exec_output(const char* cmd) {
    ExecResult result;
    result.errors = gorget_str_from_literal("", 0);

    // Capture stdout via popen
    FILE* __proc_fp = popen(cmd, "r");
    if (!__proc_fp) {
        result.output = gorget_str_from_literal("", 0);
        result.exit_code = -1;
        return result;
    }

    // Read all stdout
    size_t cap = 256;
    size_t len = 0;
    char* buf = (char*)GORGET_ALLOC(cap);
    size_t n;
    while ((n = fread(buf + len, 1, cap - len - 1, __proc_fp)) > 0) {
        len += n;
        if (len + 1 >= cap) {
            cap *= 2;
            buf = (char*)GORGET_REALLOC(buf, 0, cap);
        }
    }
    buf[len] = '\0';

    int status = pclose(__proc_fp);
    result.exit_code = WIFEXITED(status) ? (int64_t)WEXITSTATUS(status) : -1;
    result.output = (Str){ .data = buf, .len = len };
    return result;
}
"#;


/// C runtime for gg.http — HTTP requests via libcurl.

// ── gg.crypto runtime ──────────────────────────────────────
pub const CRYPTO_RUNTIME: &str = r#"
// ── Crypto Wrappers (gg.crypto) ────────────────────────────
#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <openssl/bn.h>
#include <openssl/rand.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <openssl/kdf.h>

// Opaque types wrapping OpenSSL handles
typedef struct {
    EVP_CIPHER_CTX* ctx;
} GorgetCipherContext;

typedef struct {
    BIGNUM* bn;
} GorgetBigNum;

typedef struct {
    EVP_PKEY* pkey;
} GorgetRSAKey;

// SHA-256 one-shot hash
static GorgetArray gorget_crypto_sha256(const GorgetArray* data) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    out.data = GORGET_ALLOC(32);
    out.cap = 32;
    out.len = 32;
    unsigned int md_len = 32;
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
    EVP_DigestUpdate(ctx, data->data, data->len);
    EVP_DigestFinal_ex(ctx, (unsigned char*)out.data, &md_len);
    EVP_MD_CTX_free(ctx);
    return out;
}

// SHA-1 one-shot hash
static GorgetArray gorget_crypto_sha1(const GorgetArray* data) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    out.data = GORGET_ALLOC(20);
    out.cap = 20;
    out.len = 20;
    unsigned int md_len = 20;
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha1(), NULL);
    EVP_DigestUpdate(ctx, data->data, data->len);
    EVP_DigestFinal_ex(ctx, (unsigned char*)out.data, &md_len);
    EVP_MD_CTX_free(ctx);
    return out;
}

// Crypto error infrastructure (used by Result-returning crypto functions)
static const char* __gorget_crypto_last_error = NULL;

static const char* gorget_crypto_last_error(void) {
    return __gorget_crypto_last_error;
}

// HMAC (supports "sha256" and "sha1")
static GorgetArray gorget_crypto_hmac(const char* algo, const GorgetArray* key, const GorgetArray* data) {
    __gorget_crypto_last_error = NULL;
    const EVP_MD* md = NULL;
    if (strcmp(algo, "sha256") == 0) md = EVP_sha256();
    else if (strcmp(algo, "sha1") == 0) md = EVP_sha1();
    else {
        __gorget_crypto_last_error = "unsupported HMAC algorithm";
        return gorget_array_new(sizeof(uint8_t));
    }

    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    unsigned int md_len = (unsigned int)EVP_MD_size(md);
    out.data = GORGET_ALLOC(md_len);
    out.cap = md_len;
    out.len = md_len;

    unsigned char* result = HMAC(md,
        key->data, (int)key->len,
        (unsigned char*)data->data, data->len,
        (unsigned char*)out.data, &md_len);
    (void)result;
    out.len = md_len;
    return out;
}

// AES-CTR cipher context
static GorgetCipherContext gorget_crypto_aes_ctr_new(const GorgetArray* key, const GorgetArray* iv) {
    __gorget_crypto_last_error = NULL;
    const EVP_CIPHER* cipher = NULL;
    if (key->len == 16) cipher = EVP_aes_128_ctr();
    else if (key->len == 24) cipher = EVP_aes_192_ctr();
    else if (key->len == 32) cipher = EVP_aes_256_ctr();
    else {
        __gorget_crypto_last_error = "AES key must be 16, 24, or 32 bytes";
        return (GorgetCipherContext){NULL};
    }
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        __gorget_crypto_last_error = "failed to create cipher context";
        return (GorgetCipherContext){NULL};
    }
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, (unsigned char*)key->data, (unsigned char*)iv->data)) {
        EVP_CIPHER_CTX_free(ctx);
        __gorget_crypto_last_error = "failed to initialize cipher";
        return (GorgetCipherContext){NULL};
    }
    return (GorgetCipherContext){ctx};
}

// AES-CTR encrypt (CTR mode: encrypt == decrypt)
static GorgetArray gorget_cipher_encrypt(GorgetCipherContext* c, const GorgetArray* plaintext) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    int out_len = (int)plaintext->len + 16;
    out.data = GORGET_ALLOC((size_t)out_len);
    out.cap = (size_t)out_len;
    EVP_EncryptUpdate(c->ctx, (unsigned char*)out.data, &out_len,
        (unsigned char*)plaintext->data, (int)plaintext->len);
    out.len = (size_t)out_len;
    return out;
}

// AES-CTR decrypt (same as encrypt for CTR mode)
static GorgetArray gorget_cipher_decrypt(GorgetCipherContext* c, const GorgetArray* ciphertext) {
    return gorget_cipher_encrypt(c, ciphertext);
}

// BigNum from bytes (big-endian unsigned)
static GorgetBigNum gorget_crypto_bn_from_bytes(const GorgetArray* data) {
    BIGNUM* bn = BN_bin2bn((unsigned char*)data->data, (int)data->len, NULL);
    return (GorgetBigNum){bn};
}

// BigNum to bytes (big-endian unsigned)
static GorgetArray gorget_crypto_bn_to_bytes(const GorgetBigNum* bn) {
    int n = BN_num_bytes(bn->bn);
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    out.data = GORGET_ALLOC((size_t)n);
    out.cap = (size_t)n;
    out.len = (size_t)n;
    BN_bn2bin(bn->bn, (unsigned char*)out.data);
    return out;
}

// Modular exponentiation: base^exp mod modulus
static GorgetBigNum gorget_crypto_bn_mod_exp(const GorgetBigNum* base, const GorgetBigNum* exp, const GorgetBigNum* modulus) {
    BIGNUM* result = BN_new();
    BN_CTX* ctx = BN_CTX_new();
    BN_mod_exp(result, base->bn, exp->bn, modulus->bn, ctx);
    BN_CTX_free(ctx);
    return (GorgetBigNum){result};
}

// Load RSA public key from DER-encoded bytes
static GorgetRSAKey gorget_crypto_rsa_load_public(const GorgetArray* key_bytes) {
    __gorget_crypto_last_error = NULL;
    const unsigned char* p = (const unsigned char*)key_bytes->data;
    EVP_PKEY* pkey = d2i_PUBKEY(NULL, &p, (long)key_bytes->len);
    if (!pkey) {
        __gorget_crypto_last_error = "failed to load RSA public key";
        return (GorgetRSAKey){NULL};
    }
    return (GorgetRSAKey){pkey};
}

// RSA signature verification (PKCS#1 v1.5 with SHA-256)
static bool gorget_crypto_rsa_verify(const GorgetRSAKey* key, const GorgetArray* data, const GorgetArray* sig) {
    if (!key->pkey) return false;
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestVerifyInit(ctx, NULL, EVP_sha256(), NULL, key->pkey);
    EVP_DigestVerifyUpdate(ctx, data->data, data->len);
    int ok = EVP_DigestVerifyFinal(ctx, (unsigned char*)sig->data, sig->len);
    EVP_MD_CTX_free(ctx);
    return ok == 1;
}

// Cryptographically secure random bytes (via OpenSSL RAND)
static GorgetArray gorget_crypto_random_bytes(int64_t n) {
    __gorget_crypto_last_error = NULL;
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (n <= 0) return out;
    out.data = GORGET_ALLOC((size_t)n);
    out.cap = (size_t)n;
    out.len = (size_t)n;
    if (RAND_bytes((unsigned char*)out.data, (int)n) != 1) {
        GORGET_FREE(out.data, 0);
        out.data = NULL;
        out.cap = 0;
        out.len = 0;
        __gorget_crypto_last_error = "RAND_bytes failed";
        return out;
    }
    return out;
}

// ── Ed25519 ─────────────────────────────────────────────────
typedef struct {
    EVP_PKEY* pkey;
} GorgetEd25519KeyPair;

// Generate Ed25519 keypair
static GorgetEd25519KeyPair gorget_crypto_ed25519_keygen(void) {
    __gorget_crypto_last_error = NULL;
    EVP_PKEY* pkey = NULL;
    EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_ED25519, NULL);
    if (!ctx) {
        __gorget_crypto_last_error = "failed to create Ed25519 context";
        return (GorgetEd25519KeyPair){NULL};
    }
    if (EVP_PKEY_keygen_init(ctx) <= 0 || EVP_PKEY_keygen(ctx, &pkey) <= 0) {
        EVP_PKEY_CTX_free(ctx);
        __gorget_crypto_last_error = "Ed25519 key generation failed";
        return (GorgetEd25519KeyPair){NULL};
    }
    EVP_PKEY_CTX_free(ctx);
    return (GorgetEd25519KeyPair){pkey};
}

// Extract 32-byte public key
static GorgetArray gorget_ed25519_public_key(const GorgetEd25519KeyPair* kp) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (!kp->pkey) return out;
    size_t len = 32;
    out.data = GORGET_ALLOC(32);
    out.cap = 32;
    EVP_PKEY_get_raw_public_key(kp->pkey, (unsigned char*)out.data, &len);
    out.len = (int64_t)len;
    return out;
}

// Extract 64-byte private key (Ed25519 seed is 32 bytes, but we store as 64 = seed + public)
static GorgetArray gorget_ed25519_private_key(const GorgetEd25519KeyPair* kp) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (!kp->pkey) return out;
    // Get 32-byte seed
    size_t seed_len = 32;
    uint8_t seed[32];
    EVP_PKEY_get_raw_private_key(kp->pkey, seed, &seed_len);
    // Get 32-byte public key
    size_t pub_len = 32;
    uint8_t pub_key[32];
    EVP_PKEY_get_raw_public_key(kp->pkey, pub_key, &pub_len);
    // Concatenate seed + public = 64 bytes
    out.data = GORGET_ALLOC(64);
    out.cap = 64;
    out.len = 64;
    memcpy(out.data, seed, 32);
    memcpy((uint8_t*)out.data + 32, pub_key, 32);
    return out;
}

// Sign data with Ed25519 private key (given as 64-byte seed+public or 32-byte seed)
static GorgetArray gorget_crypto_ed25519_sign(const GorgetArray* private_key, const GorgetArray* data) {
    __gorget_crypto_last_error = NULL;
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (private_key->len < 32) {
        __gorget_crypto_last_error = "Ed25519 private key too short";
        return out;
    }
    // Use first 32 bytes as seed
    EVP_PKEY* pkey = EVP_PKEY_new_raw_private_key(EVP_PKEY_ED25519, NULL,
        (const unsigned char*)private_key->data, 32);
    if (!pkey) {
        __gorget_crypto_last_error = "invalid Ed25519 private key";
        return out;
    }
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    size_t sig_len = 64;
    out.data = GORGET_ALLOC(64);
    out.cap = 64;
    if (EVP_DigestSignInit(ctx, NULL, NULL, NULL, pkey) <= 0 ||
        EVP_DigestSign(ctx, (unsigned char*)out.data, &sig_len,
            (const unsigned char*)data->data, (size_t)data->len) <= 0) {
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(pkey);
        GORGET_FREE(out.data, 0);
        out.data = NULL;
        out.cap = 0;
        __gorget_crypto_last_error = "Ed25519 signing failed";
        return out;
    }
    out.len = (int64_t)sig_len;
    EVP_MD_CTX_free(ctx);
    EVP_PKEY_free(pkey);
    return out;
}

// Verify Ed25519 signature
static bool gorget_crypto_ed25519_verify(const GorgetArray* public_key, const GorgetArray* data, const GorgetArray* signature) {
    if (public_key->len != 32 || signature->len != 64) return false;
    EVP_PKEY* pkey = EVP_PKEY_new_raw_public_key(EVP_PKEY_ED25519, NULL,
        (const unsigned char*)public_key->data, 32);
    if (!pkey) return false;
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    int ok = 0;
    if (EVP_DigestVerifyInit(ctx, NULL, NULL, NULL, pkey) > 0) {
        ok = EVP_DigestVerify(ctx, (const unsigned char*)signature->data, (size_t)signature->len,
            (const unsigned char*)data->data, (size_t)data->len);
    }
    EVP_MD_CTX_free(ctx);
    EVP_PKEY_free(pkey);
    return ok == 1;
}

// ── X25519 ECDH ─────────────────────────────────────────────
typedef struct {
    EVP_PKEY* pkey;
} GorgetX25519KeyPair;

// Generate ephemeral X25519 keypair
static GorgetX25519KeyPair gorget_crypto_x25519_keygen(void) {
    __gorget_crypto_last_error = NULL;
    EVP_PKEY* pkey = NULL;
    EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_X25519, NULL);
    if (!ctx) {
        __gorget_crypto_last_error = "failed to create X25519 context";
        return (GorgetX25519KeyPair){NULL};
    }
    if (EVP_PKEY_keygen_init(ctx) <= 0 || EVP_PKEY_keygen(ctx, &pkey) <= 0) {
        EVP_PKEY_CTX_free(ctx);
        __gorget_crypto_last_error = "X25519 key generation failed";
        return (GorgetX25519KeyPair){NULL};
    }
    EVP_PKEY_CTX_free(ctx);
    return (GorgetX25519KeyPair){pkey};
}

// Extract 32-byte public key from X25519 keypair
static GorgetArray gorget_crypto_x25519_public(const GorgetX25519KeyPair* kp) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (!kp->pkey) return out;
    size_t len = 32;
    out.data = GORGET_ALLOC(32);
    out.cap = 32;
    EVP_PKEY_get_raw_public_key(kp->pkey, (unsigned char*)out.data, &len);
    out.len = (int64_t)len;
    return out;
}

// Extract 32-byte raw private key from X25519 keypair
static GorgetArray gorget_crypto_x25519_private(const GorgetX25519KeyPair* kp) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (!kp->pkey) return out;
    size_t len = 32;
    out.data = GORGET_ALLOC(32);
    out.cap = 32;
    EVP_PKEY_get_raw_private_key(kp->pkey, (unsigned char*)out.data, &len);
    out.len = (int64_t)len;
    return out;
}

// Compute shared secret from raw 32-byte private key bytes + raw 32-byte peer public key
static GorgetArray gorget_crypto_x25519_dh(const GorgetArray* private_key_bytes, const GorgetArray* peer_public) {
    __gorget_crypto_last_error = NULL;
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (private_key_bytes->len != 32 || peer_public->len != 32) {
        __gorget_crypto_last_error = "X25519 keys must be 32 bytes";
        return out;
    }
    EVP_PKEY* our_pkey = EVP_PKEY_new_raw_private_key(EVP_PKEY_X25519, NULL,
        (const unsigned char*)private_key_bytes->data, 32);
    if (!our_pkey) {
        __gorget_crypto_last_error = "failed to load X25519 private key";
        return out;
    }
    EVP_PKEY* peer_pkey = EVP_PKEY_new_raw_public_key(EVP_PKEY_X25519, NULL,
        (const unsigned char*)peer_public->data, 32);
    if (!peer_pkey) {
        EVP_PKEY_free(our_pkey);
        __gorget_crypto_last_error = "failed to load peer X25519 public key";
        return out;
    }
    EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new(our_pkey, NULL);
    if (!ctx || EVP_PKEY_derive_init(ctx) <= 0 || EVP_PKEY_derive_set_peer(ctx, peer_pkey) <= 0) {
        if (ctx) EVP_PKEY_CTX_free(ctx);
        EVP_PKEY_free(our_pkey);
        EVP_PKEY_free(peer_pkey);
        __gorget_crypto_last_error = "X25519 derive init failed";
        return out;
    }
    size_t secret_len = 32;
    out.data = GORGET_ALLOC(32);
    out.cap = 32;
    if (EVP_PKEY_derive(ctx, (unsigned char*)out.data, &secret_len) <= 0) {
        GORGET_FREE(out.data, 0);
        out.data = NULL;
        out.cap = 0;
        EVP_PKEY_CTX_free(ctx);
        EVP_PKEY_free(our_pkey);
        EVP_PKEY_free(peer_pkey);
        __gorget_crypto_last_error = "X25519 key derivation failed";
        return out;
    }
    out.len = (int64_t)secret_len;
    EVP_PKEY_CTX_free(ctx);
    EVP_PKEY_free(our_pkey);
    EVP_PKEY_free(peer_pkey);
    return out;
}

// Compute 32-byte shared secret from our X25519 keypair + peer's raw 32-byte public key
static GorgetArray gorget_crypto_x25519_shared_secret(const GorgetX25519KeyPair* private_key, const GorgetArray* peer_public) {
    __gorget_crypto_last_error = NULL;
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (!private_key->pkey || peer_public->len != 32) {
        __gorget_crypto_last_error = "invalid X25519 key material";
        return out;
    }
    EVP_PKEY* peer_pkey = EVP_PKEY_new_raw_public_key(EVP_PKEY_X25519, NULL,
        (const unsigned char*)peer_public->data, 32);
    if (!peer_pkey) {
        __gorget_crypto_last_error = "failed to load peer X25519 public key";
        return out;
    }
    EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new(private_key->pkey, NULL);
    if (!ctx || EVP_PKEY_derive_init(ctx) <= 0 || EVP_PKEY_derive_set_peer(ctx, peer_pkey) <= 0) {
        if (ctx) EVP_PKEY_CTX_free(ctx);
        EVP_PKEY_free(peer_pkey);
        __gorget_crypto_last_error = "X25519 derive init failed";
        return out;
    }
    size_t secret_len = 32;
    out.data = GORGET_ALLOC(32);
    out.cap = 32;
    if (EVP_PKEY_derive(ctx, (unsigned char*)out.data, &secret_len) <= 0) {
        GORGET_FREE(out.data, 0);
        out.data = NULL;
        out.cap = 0;
        EVP_PKEY_CTX_free(ctx);
        EVP_PKEY_free(peer_pkey);
        __gorget_crypto_last_error = "X25519 key derivation failed";
        return out;
    }
    out.len = (int64_t)secret_len;
    EVP_PKEY_CTX_free(ctx);
    EVP_PKEY_free(peer_pkey);
    return out;
}

// ── HKDF-SHA256 ─────────────────────────────────────────────
static GorgetArray gorget_crypto_hkdf_sha256(const GorgetArray* salt, const GorgetArray* ikm, const GorgetArray* info, int64_t length) {
    __gorget_crypto_last_error = NULL;
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (length <= 0 || length > 255 * 32) {
        __gorget_crypto_last_error = "HKDF output length out of range";
        return out;
    }
    EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HKDF, NULL);
    if (!ctx) {
        __gorget_crypto_last_error = "failed to create HKDF context";
        return out;
    }
    if (EVP_PKEY_derive_init(ctx) <= 0 ||
        EVP_PKEY_CTX_set_hkdf_md(ctx, EVP_sha256()) <= 0 ||
        EVP_PKEY_CTX_set1_hkdf_salt(ctx, (const unsigned char*)salt->data, (int)salt->len) <= 0 ||
        EVP_PKEY_CTX_set1_hkdf_key(ctx, (const unsigned char*)ikm->data, (int)ikm->len) <= 0 ||
        EVP_PKEY_CTX_add1_hkdf_info(ctx, (const unsigned char*)info->data, (int)info->len) <= 0) {
        EVP_PKEY_CTX_free(ctx);
        __gorget_crypto_last_error = "HKDF parameter setup failed";
        return out;
    }
    size_t out_len = (size_t)length;
    out.data = GORGET_ALLOC(out_len);
    out.cap = (int64_t)out_len;
    if (EVP_PKEY_derive(ctx, (unsigned char*)out.data, &out_len) <= 0) {
        GORGET_FREE(out.data, 0);
        out.data = NULL;
        out.cap = 0;
        EVP_PKEY_CTX_free(ctx);
        __gorget_crypto_last_error = "HKDF derivation failed";
        return out;
    }
    out.len = (int64_t)out_len;
    EVP_PKEY_CTX_free(ctx);
    return out;
}

// ── AES-256-GCM AEAD ────────────────────────────────────────

// Encrypt: key (32B), nonce (12B), plaintext → returns [12B nonce | ciphertext | 16B tag]
static GorgetArray gorget_crypto_aes_gcm_encrypt(const GorgetArray* key, const GorgetArray* nonce, const GorgetArray* plaintext) {
    __gorget_crypto_last_error = NULL;
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (key->len != 32) { __gorget_crypto_last_error = "AES-GCM key must be 32 bytes"; return out; }
    if (nonce->len != 12) { __gorget_crypto_last_error = "AES-GCM nonce must be 12 bytes"; return out; }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) { __gorget_crypto_last_error = "failed to create cipher context"; return out; }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL) != 1 ||
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL) != 1 ||
        EVP_EncryptInit_ex(ctx, NULL, NULL, (const unsigned char*)key->data, (const unsigned char*)nonce->data) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        __gorget_crypto_last_error = "AES-GCM encrypt init failed";
        return out;
    }

    // Output: 12B nonce + ciphertext (same len as plaintext) + 16B tag
    size_t total = 12 + (size_t)plaintext->len + 16;
    out.data = GORGET_ALLOC(total);
    out.cap = (int64_t)total;

    // Copy nonce to output
    memcpy(out.data, nonce->data, 12);

    int ct_len = 0;
    if (EVP_EncryptUpdate(ctx, (unsigned char*)out.data + 12, &ct_len,
            (const unsigned char*)plaintext->data, (int)plaintext->len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        GORGET_FREE(out.data, 0); out.data = NULL; out.cap = 0;
        __gorget_crypto_last_error = "AES-GCM encrypt update failed";
        return out;
    }

    int final_len = 0;
    if (EVP_EncryptFinal_ex(ctx, (unsigned char*)out.data + 12 + ct_len, &final_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        GORGET_FREE(out.data, 0); out.data = NULL; out.cap = 0;
        __gorget_crypto_last_error = "AES-GCM encrypt final failed";
        return out;
    }
    ct_len += final_len;

    // Append 16-byte tag
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, (unsigned char*)out.data + 12 + ct_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        GORGET_FREE(out.data, 0); out.data = NULL; out.cap = 0;
        __gorget_crypto_last_error = "AES-GCM get tag failed";
        return out;
    }

    out.len = (int64_t)(12 + ct_len + 16);
    EVP_CIPHER_CTX_free(ctx);
    return out;
}

// Decrypt: key (32B), ciphertext ([12B nonce | ct | 16B tag]) → plaintext
static GorgetArray gorget_crypto_aes_gcm_decrypt(const GorgetArray* key, const GorgetArray* ciphertext) {
    __gorget_crypto_last_error = NULL;
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (key->len != 32) { __gorget_crypto_last_error = "AES-GCM key must be 32 bytes"; return out; }
    if (ciphertext->len < 28) { __gorget_crypto_last_error = "AES-GCM ciphertext too short"; return out; }

    const unsigned char* nonce = (const unsigned char*)ciphertext->data;
    int ct_len = (int)ciphertext->len - 12 - 16;
    const unsigned char* ct = (const unsigned char*)ciphertext->data + 12;
    const unsigned char* tag = (const unsigned char*)ciphertext->data + 12 + ct_len;

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) { __gorget_crypto_last_error = "failed to create cipher context"; return out; }

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL) != 1 ||
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL) != 1 ||
        EVP_DecryptInit_ex(ctx, NULL, NULL, (const unsigned char*)key->data, nonce) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        __gorget_crypto_last_error = "AES-GCM decrypt init failed";
        return out;
    }

    out.data = GORGET_ALLOC((size_t)ct_len);
    out.cap = (int64_t)ct_len;

    int pt_len = 0;
    if (EVP_DecryptUpdate(ctx, (unsigned char*)out.data, &pt_len, ct, ct_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        GORGET_FREE(out.data, 0); out.data = NULL; out.cap = 0;
        __gorget_crypto_last_error = "AES-GCM decrypt update failed";
        return out;
    }

    // Set expected tag
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, (void*)tag) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        GORGET_FREE(out.data, 0); out.data = NULL; out.cap = 0;
        __gorget_crypto_last_error = "AES-GCM set tag failed";
        return out;
    }

    int final_len = 0;
    if (EVP_DecryptFinal_ex(ctx, (unsigned char*)out.data + pt_len, &final_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        GORGET_FREE(out.data, 0); out.data = NULL; out.cap = 0;
        __gorget_crypto_last_error = "AES-GCM authentication failed";
        return out;
    }
    pt_len += final_len;

    out.len = (int64_t)pt_len;
    EVP_CIPHER_CTX_free(ctx);
    return out;
}

"#;

// ── std.net.socket runtime ───────────────────────────────────
pub const SOCKET_RUNTIME: &str = r#"
// ── TCP Socket (std.net.socket) ─────────────────────────────
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <sys/time.h>

typedef struct {
    int fd;
} GorgetSocket;

// Connect to host:port, returning a socket fd or -1 on error
static const char* __gorget_socket_last_error = NULL;

static GorgetSocket gorget_socket_connect(const char* host, int64_t port) {
    __gorget_socket_last_error = NULL;
    char port_str[16];
    snprintf(port_str, sizeof(port_str), "%lld", (long long)port);

    struct addrinfo hints, *res, *rp;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int err = getaddrinfo(host, port_str, &hints, &res);
    if (err != 0) {
        __gorget_socket_last_error = gai_strerror(err);
        return (GorgetSocket){-1};
    }

    int fd = -1;
    for (rp = res; rp != NULL; rp = rp->ai_next) {
        fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (fd < 0) continue;
        if (connect(fd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(fd);
        fd = -1;
    }
    freeaddrinfo(res);

    if (fd < 0) {
        __gorget_socket_last_error = strerror(errno);
        return (GorgetSocket){-1};
    }
    return (GorgetSocket){fd};
}

static const char* gorget_socket_last_error(void) {
    return __gorget_socket_last_error;
}

// Read up to n bytes; returns a GorgetArray of uint8
static GorgetArray gorget_socket_read(GorgetSocket* sock, int64_t n) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (n <= 0 || sock->fd < 0) return arr;
    uint8_t* buf = (uint8_t*)GORGET_ALLOC((size_t)n);
    ssize_t got = recv(sock->fd, buf, (size_t)n, 0);
    if (got > 0) {
        arr.data = buf;
        arr.len = (size_t)got;
        arr.cap = (size_t)n;
    } else {
        GORGET_FREE(buf, 0);
    }
    return arr;
}

// Read exactly n bytes (loops until complete or error)
static GorgetArray gorget_socket_read_exact(GorgetSocket* sock, int64_t n) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (n <= 0 || sock->fd < 0) return arr;
    uint8_t* buf = (uint8_t*)GORGET_ALLOC((size_t)n);
    size_t total = 0;
    while (total < (size_t)n) {
        ssize_t got = recv(sock->fd, buf + total, (size_t)n - total, 0);
        if (got <= 0) break;
        total += (size_t)got;
    }
    if (total == (size_t)n) {
        arr.data = buf;
        arr.len = (size_t)n;
        arr.cap = (size_t)n;
    } else {
        GORGET_FREE(buf, 0);
    }
    return arr;
}

// Write all bytes (loops until complete)
static int64_t gorget_socket_write(GorgetSocket* sock, const GorgetArray* data) {
    if (sock->fd < 0 || data->len == 0) return 0;
    size_t total = 0;
    while (total < data->len) {
        ssize_t sent = send(sock->fd, (uint8_t*)data->data + total, data->len - total, 0);
        if (sent <= 0) return -1;
        total += (size_t)sent;
    }
    return (int64_t)total;
}

// Write a str (convenience for text protocols)
static int64_t gorget_socket_write_str(GorgetSocket* sock, const char* s) {
    if (sock->fd < 0 || !s) return 0;
    size_t len = strlen(s);
    size_t total = 0;
    while (total < len) {
        ssize_t sent = send(sock->fd, s + total, len - total, 0);
        if (sent <= 0) return -1;
        total += (size_t)sent;
    }
    return (int64_t)total;
}

// Read until \n, return as String (for text protocols like SSH banner)
static GorgetString gorget_socket_read_line(GorgetSocket* sock) {
    if (sock->fd < 0) return (GorgetString){"", 0, 0};
    size_t cap = 256, len = 0;
    char* buf = (char*)GORGET_ALLOC(cap);
    while (1) {
        char c;
        ssize_t got = recv(sock->fd, &c, 1, 0);
        if (got <= 0) break;
        if (len + 1 >= cap) {
            cap *= 2;
            buf = (char*)GORGET_REALLOC(buf, 0, cap);
        }
        buf[len++] = c;
        if (c == '\n') break;
    }
    buf[len] = '\0';
    // Strip trailing \r\n
    while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r')) {
        buf[--len] = '\0';
    }
    return gorget_string_adopt(buf);
}

// Set socket timeout in milliseconds
static void gorget_socket_set_timeout(GorgetSocket* sock, int64_t ms) {
    if (sock->fd < 0) return;
    struct timeval tv;
    tv.tv_sec = ms / 1000;
    tv.tv_usec = (ms % 1000) * 1000;
    setsockopt(sock->fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(sock->fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
}

// Close the socket
static void gorget_socket_close(GorgetSocket* sock) {
    if (sock->fd >= 0) {
        close(sock->fd);
        sock->fd = -1;
    }
}

"#;

// ── std.net.udp runtime ─────────────────────────────────────
pub const UDP_SOCKET_RUNTIME: &str = r#"
// ── UDP Socket (std.net.udp) ────────────────────────────────
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <poll.h>

typedef struct {
    int fd;
} GorgetUdpSocket;

typedef struct {
    Str host;
    int64_t port;
} GorgetUdpAddr;

typedef struct {
    GorgetArray data;
    GorgetUdpAddr sender;
} GorgetUdpPacket;

static const char* __gorget_udp_last_error = NULL;

static const char* gorget_udp_last_error(void) {
    return __gorget_udp_last_error;
}

static GorgetUdpSocket gorget_udp_bind(const char* addr, int64_t port) {
    __gorget_udp_last_error = NULL;
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        __gorget_udp_last_error = strerror(errno);
        return (GorgetUdpSocket){-1};
    }

    int opt = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
#ifdef SO_REUSEPORT
    setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &opt, sizeof(opt));
#endif

    struct sockaddr_in sa;
    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons((uint16_t)port);
    if (inet_pton(AF_INET, addr, &sa.sin_addr) <= 0) {
        sa.sin_addr.s_addr = INADDR_ANY;
    }

    if (bind(fd, (struct sockaddr*)&sa, sizeof(sa)) < 0) {
        __gorget_udp_last_error = strerror(errno);
        close(fd);
        return (GorgetUdpSocket){-1};
    }
    return (GorgetUdpSocket){fd};
}

static int64_t gorget_udp_sendto(GorgetUdpSocket* sock, const GorgetArray* data, const char* host, int64_t port) {
    __gorget_udp_last_error = NULL;
    struct sockaddr_in sa;
    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons((uint16_t)port);
    if (inet_pton(AF_INET, host, &sa.sin_addr) <= 0) {
        // Try hostname resolution
        struct hostent* he = gethostbyname(host);
        if (!he) {
            __gorget_udp_last_error = "hostname resolution failed";
            return -1;
        }
        memcpy(&sa.sin_addr, he->h_addr_list[0], (size_t)he->h_length);
    }

    ssize_t sent = sendto(sock->fd, data->data, (size_t)(data->len * data->elem_size),
                          0, (struct sockaddr*)&sa, sizeof(sa));
    if (sent < 0) {
        __gorget_udp_last_error = strerror(errno);
        return -1;
    }
    return (int64_t)sent;
}

static GorgetUdpPacket gorget_udp_recvfrom(GorgetUdpSocket* sock, int64_t max_bytes) {
    __gorget_udp_last_error = NULL;
    GorgetUdpPacket pkt;
    memset(&pkt, 0, sizeof(pkt));

    uint8_t* buf = (uint8_t*)GORGET_ALLOC((size_t)max_bytes);
    if (!buf) {
        __gorget_udp_last_error = "out of memory";
        return pkt;
    }

    struct sockaddr_in sender_addr;
    socklen_t addr_len = sizeof(sender_addr);
    ssize_t n = recvfrom(sock->fd, buf, (size_t)max_bytes, 0,
                         (struct sockaddr*)&sender_addr, &addr_len);
    if (n < 0) {
        __gorget_udp_last_error = strerror(errno);
        GORGET_FREE(buf, 0);
        return pkt;
    }

    // Build data array
    pkt.data.data = buf;
    pkt.data.len = (int64_t)n;
    pkt.data.cap = max_bytes;
    pkt.data.elem_size = 1;

    // Build sender address
    static __thread char sender_host[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &sender_addr.sin_addr, sender_host, sizeof(sender_host));
    pkt.sender.host = gorget_str_from_cstr(sender_host);
    pkt.sender.port = (int64_t)ntohs(sender_addr.sin_port);

    return pkt;
}

static bool gorget_udp_poll(GorgetUdpSocket* sock, int64_t timeout_ms) {
    struct pollfd pfd;
    pfd.fd = sock->fd;
    pfd.events = POLLIN;
    pfd.revents = 0;
    int ret = poll(&pfd, 1, (int)timeout_ms);
    return ret > 0 && (pfd.revents & POLLIN);
}

static void gorget_udp_set_nonblocking(GorgetUdpSocket* sock, bool enabled) {
    int flags = fcntl(sock->fd, F_GETFL, 0);
    if (enabled) {
        fcntl(sock->fd, F_SETFL, flags | O_NONBLOCK);
    } else {
        fcntl(sock->fd, F_SETFL, flags & ~O_NONBLOCK);
    }
}

static bool gorget_udp_join_multicast(GorgetUdpSocket* sock, const char* group_addr) {
    __gorget_udp_last_error = NULL;
    struct ip_mreq mreq;
    memset(&mreq, 0, sizeof(mreq));
    if (inet_pton(AF_INET, group_addr, &mreq.imr_multiaddr) <= 0) {
        __gorget_udp_last_error = "invalid multicast address";
        return false;
    }
    mreq.imr_interface.s_addr = INADDR_ANY;
    if (setsockopt(sock->fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        __gorget_udp_last_error = strerror(errno);
        return false;
    }
    return true;
}

static void gorget_udp_leave_multicast(GorgetUdpSocket* sock, const char* group_addr) {
    struct ip_mreq mreq;
    memset(&mreq, 0, sizeof(mreq));
    inet_pton(AF_INET, group_addr, &mreq.imr_multiaddr);
    mreq.imr_interface.s_addr = INADDR_ANY;
    setsockopt(sock->fd, IPPROTO_IP, IP_DROP_MEMBERSHIP, &mreq, sizeof(mreq));
}

static void gorget_udp_set_multicast_loopback(GorgetUdpSocket* sock, bool enabled) {
    uint8_t val = enabled ? 1 : 0;
    setsockopt(sock->fd, IPPROTO_IP, IP_MULTICAST_LOOP, &val, sizeof(val));
}

static GorgetUdpAddr gorget_udp_local_addr(GorgetUdpSocket* sock) {
    GorgetUdpAddr addr;
    memset(&addr, 0, sizeof(addr));
    struct sockaddr_in sa;
    socklen_t len = sizeof(sa);
    if (getsockname(sock->fd, (struct sockaddr*)&sa, &len) == 0) {
        static __thread char host_buf[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &sa.sin_addr, host_buf, sizeof(host_buf));
        addr.host = gorget_str_from_cstr(host_buf);
        addr.port = (int64_t)ntohs(sa.sin_port);
    }
    return addr;
}

static void gorget_udp_close(GorgetUdpSocket* sock) {
    if (sock->fd >= 0) {
        close(sock->fd);
        sock->fd = -1;
    }
}

"#;

// ── std.net.tls runtime ─────────────────────────────────────
pub const TLS_SOCKET_RUNTIME: &str = r#"
// ── TLS Socket (std.net.tls) ────────────────────────────────
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>

typedef struct {
    int fd;
    SSL_CTX* ctx;
    SSL* ssl;
} GorgetTlsSocket;

static const char* __gorget_tls_last_error = NULL;

static GorgetTlsSocket gorget_tls_connect(const char* host, int64_t port) {
    __gorget_tls_last_error = NULL;
    GorgetTlsSocket sock = {-1, NULL, NULL};

    // DNS resolution
    char port_str[16];
    snprintf(port_str, sizeof(port_str), "%lld", (long long)port);
    struct addrinfo hints, *res, *rp;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    int err = getaddrinfo(host, port_str, &hints, &res);
    if (err != 0) {
        __gorget_tls_last_error = gai_strerror(err);
        return sock;
    }

    // TCP connect
    int fd = -1;
    for (rp = res; rp != NULL; rp = rp->ai_next) {
        fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (fd < 0) continue;
        if (connect(fd, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(fd);
        fd = -1;
    }
    freeaddrinfo(res);
    if (fd < 0) {
        __gorget_tls_last_error = "TCP connection failed";
        return sock;
    }

    // SSL setup
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        close(fd);
        __gorget_tls_last_error = "SSL_CTX_new failed";
        return sock;
    }
    SSL_CTX_set_default_verify_paths(ctx);

    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        SSL_CTX_free(ctx);
        close(fd);
        __gorget_tls_last_error = "SSL_new failed";
        return sock;
    }

    SSL_set_fd(ssl, fd);
    SSL_set_tlsext_host_name(ssl, host);  // SNI

    if (SSL_connect(ssl) != 1) {
        __gorget_tls_last_error = "TLS handshake failed";
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(fd);
        return (GorgetTlsSocket){-1, NULL, NULL};
    }

    // Verify certificate
    long verify_result = SSL_get_verify_result(ssl);
    if (verify_result != X509_V_OK) {
        __gorget_tls_last_error = X509_verify_cert_error_string(verify_result);
        SSL_shutdown(ssl);
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        close(fd);
        return (GorgetTlsSocket){-1, NULL, NULL};
    }

    return (GorgetTlsSocket){fd, ctx, ssl};
}

static const char* gorget_tls_last_error(void) {
    return __gorget_tls_last_error;
}

static GorgetArray gorget_tls_read(GorgetTlsSocket* sock, int64_t n) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (n <= 0 || !sock->ssl) return arr;
    uint8_t* buf = (uint8_t*)GORGET_ALLOC((size_t)n);
    int got = SSL_read(sock->ssl, buf, (int)n);
    if (got > 0) {
        arr.data = buf;
        arr.len = (size_t)got;
        arr.cap = (size_t)n;
    } else {
        GORGET_FREE(buf, 0);
    }
    return arr;
}

static GorgetArray gorget_tls_read_exact(GorgetTlsSocket* sock, int64_t n) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (n <= 0 || !sock->ssl) return arr;
    uint8_t* buf = (uint8_t*)GORGET_ALLOC((size_t)n);
    size_t total = 0;
    while (total < (size_t)n) {
        int got = SSL_read(sock->ssl, buf + total, (int)((size_t)n - total));
        if (got <= 0) break;
        total += (size_t)got;
    }
    if (total == (size_t)n) {
        arr.data = buf;
        arr.len = (size_t)n;
        arr.cap = (size_t)n;
    } else {
        GORGET_FREE(buf, 0);
    }
    return arr;
}

static int64_t gorget_tls_write(GorgetTlsSocket* sock, const GorgetArray* data) {
    if (!sock->ssl || data->len == 0) return 0;
    size_t total = 0;
    while (total < data->len) {
        int sent = SSL_write(sock->ssl, (uint8_t*)data->data + total, (int)(data->len - total));
        if (sent <= 0) return -1;
        total += (size_t)sent;
    }
    return (int64_t)total;
}

static int64_t gorget_tls_write_str(GorgetTlsSocket* sock, const char* s) {
    if (!sock->ssl || !s) return 0;
    size_t len = strlen(s);
    size_t total = 0;
    while (total < len) {
        int sent = SSL_write(sock->ssl, s + total, (int)(len - total));
        if (sent <= 0) return -1;
        total += (size_t)sent;
    }
    return (int64_t)total;
}

static GorgetString gorget_tls_read_line(GorgetTlsSocket* sock) {
    if (!sock->ssl) return (GorgetString){"", 0, 0};
    size_t cap = 256, len = 0;
    char* buf = (char*)GORGET_ALLOC(cap);
    while (1) {
        char c;
        int got = SSL_read(sock->ssl, &c, 1);
        if (got <= 0) break;
        if (len + 1 >= cap) {
            cap *= 2;
            buf = (char*)GORGET_REALLOC(buf, 0, cap);
        }
        buf[len++] = c;
        if (c == '\n') break;
    }
    buf[len] = '\0';
    // Strip trailing \r\n
    while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r')) {
        buf[--len] = '\0';
    }
    return gorget_string_adopt(buf);
}

static void gorget_tls_close(GorgetTlsSocket* sock) {
    if (sock->ssl) {
        SSL_shutdown(sock->ssl);
        SSL_free(sock->ssl);
        sock->ssl = NULL;
    }
    if (sock->ctx) {
        SSL_CTX_free(sock->ctx);
        sock->ctx = NULL;
    }
    if (sock->fd >= 0) {
        close(sock->fd);
        sock->fd = -1;
    }
}

"#;

// ── std.bytes runtime ───────────────────────────────────────
pub const BYTES_RUNTIME: &str = r#"
// ── Byte Buffer Helpers (std.bytes) ─────────────────────────

// Convert a str to Vector[uint8]
static inline GorgetArray gorget_bytes_from_str(const char* s) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (s) {
        size_t len = strlen(s);
        for (size_t i = 0; i < len; i++) {
            uint8_t b = (uint8_t)s[i];
            gorget_array_push(&arr, &b);
        }
    }
    return arr;
}

// Convert Vector[uint8] to a null-terminated str
static inline const char* gorget_bytes_to_str(const GorgetArray* arr) {
    size_t len = arr->len;
    char* s = (char*)GORGET_ALLOC(len + 1);
    if (len > 0) memcpy(s, arr->data, len);
    s[len] = '\0';
    return s;
}

// Validate that a Vector[uint8] contains well-formed UTF-8.
// Returns 1 (true) if valid, 0 (false) if the byte sequence is invalid UTF-8.
static inline int gorget_bytes_utf8_valid(const GorgetArray* arr) {
    const uint8_t* p = (const uint8_t*)arr->data;
    size_t len = arr->len;
    size_t i = 0;
    while (i < len) {
        uint8_t b = p[i];
        int seq; // expected number of continuation bytes
        uint32_t cp; // codepoint accumulator for range checks
        if (b < 0x80) {
            // ASCII — single byte
            i++; continue;
        } else if (b < 0xC2) {
            // 0x80-0xBF: stray continuation; 0xC0-0xC1: overlong 2-byte
            return 0;
        } else if (b < 0xE0) {
            seq = 1; cp = b & 0x1F;
        } else if (b < 0xF0) {
            seq = 2; cp = b & 0x0F;
        } else if (b <= 0xF4) {
            seq = 3; cp = b & 0x07;
        } else {
            // 0xF5+ are invalid in UTF-8
            return 0;
        }
        i++;
        for (int j = 0; j < seq; j++, i++) {
            if (i >= len) return 0; // truncated sequence
            uint8_t c = p[i];
            if ((c & 0xC0) != 0x80) return 0; // not a continuation byte
            cp = (cp << 6) | (c & 0x3F);
        }
        // Range checks: reject surrogates and codepoints > U+10FFFF,
        // and catch overlong 3-byte sequences (cp < 0x800).
        if (seq == 2 && cp < 0x800) return 0;
        if (seq == 3 && (cp < 0x10000 || cp > 0x10FFFF)) return 0;
        if (cp >= 0xD800 && cp <= 0xDFFF) return 0; // UTF-16 surrogates
    }
    return 1;
}

// Convert a hex string to Vector[uint8]
static inline GorgetArray gorget_bytes_from_hex(const char* hex) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (!hex) return arr;
    size_t len = strlen(hex);
    for (size_t i = 0; i + 1 < len; i += 2) {
        char buf[3] = { hex[i], hex[i+1], '\0' };
        uint8_t b = (uint8_t)strtoul(buf, NULL, 16);
        gorget_array_push(&arr, &b);
    }
    return arr;
}

// Write a big-endian uint32 at offset into Vector[uint8]
static inline void gorget_bytes_write_u32_be(GorgetArray* arr, int64_t offset, int64_t value) {
    if (offset < 0 || (size_t)(offset + 4) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_write_u32_be: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    uint8_t* p = (uint8_t*)arr->data + offset;
    uint32_t v = (uint32_t)value;
    p[0] = (v >> 24) & 0xFF;
    p[1] = (v >> 16) & 0xFF;
    p[2] = (v >> 8) & 0xFF;
    p[3] = v & 0xFF;
}

// Read a big-endian uint32 from offset in Vector[uint8]
static inline int64_t gorget_bytes_read_u32_be(const GorgetArray* arr, int64_t offset) {
    if (offset < 0 || (size_t)(offset + 4) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_read_u32_be: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    const uint8_t* p = (const uint8_t*)arr->data + offset;
    return (int64_t)(((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3]);
}

// Concatenate two Vector[uint8]
static inline GorgetArray gorget_bytes_concat(const GorgetArray* a, const GorgetArray* b) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    size_t total = a->len + b->len;
    if (total > 0) {
        arr.data = GORGET_ALLOC(total * sizeof(uint8_t));
        arr.cap = total;
        if (a->len > 0) memcpy(arr.data, a->data, a->len);
        if (b->len > 0) memcpy((uint8_t*)arr.data + a->len, b->data, b->len);
        arr.len = total;
    }
    return arr;
}

// Slice a Vector[uint8] from start to end (exclusive)
static inline GorgetArray gorget_bytes_slice(const GorgetArray* arr, int64_t start, int64_t end) {
    GorgetArray out = gorget_array_new(sizeof(uint8_t));
    if (start < 0) start = 0;
    if (end > (int64_t)arr->len) end = (int64_t)arr->len;
    if (start >= end) return out;
    size_t count = (size_t)(end - start);
    out.data = GORGET_ALLOC(count * sizeof(uint8_t));
    out.cap = count;
    memcpy(out.data, (uint8_t*)arr->data + start, count);
    out.len = count;
    return out;
}

// Generate random bytes using /dev/urandom
static inline GorgetArray gorget_random_bytes(int64_t n) {
    GorgetArray arr = gorget_array_new(sizeof(uint8_t));
    if (n <= 0) return arr;
    arr.data = GORGET_ALLOC((size_t)n);
    arr.cap = (size_t)n;
    arr.len = (size_t)n;
    FILE* f = fopen("/dev/urandom", "rb");
    if (!f) {
        fprintf(stderr, "gorget: panic: cannot open /dev/urandom\n");
        exit(1);
    }
    if (fread(arr.data, 1, (size_t)n, f) != (size_t)n) {
        fprintf(stderr, "gorget: panic: short read from /dev/urandom\n");
        fclose(f);
        exit(1);
    }
    fclose(f);
    return arr;
}

// Write a big-endian uint16 at offset
static inline void gorget_bytes_write_u16_be(GorgetArray* arr, int64_t offset, int64_t value) {
    if (offset < 0 || (size_t)(offset + 2) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_write_u16_be: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    uint8_t* p = (uint8_t*)arr->data + offset;
    uint16_t v = (uint16_t)value;
    p[0] = (v >> 8) & 0xFF;
    p[1] = v & 0xFF;
}

// Read a big-endian uint16 from offset
static inline int64_t gorget_bytes_read_u16_be(const GorgetArray* arr, int64_t offset) {
    if (offset < 0 || (size_t)(offset + 2) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_read_u16_be: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    const uint8_t* p = (const uint8_t*)arr->data + offset;
    return (int64_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

// Write a little-endian uint32 at offset into Vector[uint8]
static inline void gorget_bytes_write_u32_le(GorgetArray* arr, int64_t offset, int64_t value) {
    if (offset < 0 || (size_t)(offset + 4) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_write_u32_le: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    uint8_t* p = (uint8_t*)arr->data + offset;
    uint32_t v = (uint32_t)value;
    p[0] = v & 0xFF;
    p[1] = (v >> 8) & 0xFF;
    p[2] = (v >> 16) & 0xFF;
    p[3] = (v >> 24) & 0xFF;
}

// Read a little-endian uint32 from offset in Vector[uint8]
static inline int64_t gorget_bytes_read_u32_le(const GorgetArray* arr, int64_t offset) {
    if (offset < 0 || (size_t)(offset + 4) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_read_u32_le: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    const uint8_t* p = (const uint8_t*)arr->data + offset;
    return (int64_t)((uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24));
}

// Write a little-endian uint16 at offset
static inline void gorget_bytes_write_u16_le(GorgetArray* arr, int64_t offset, int64_t value) {
    if (offset < 0 || (size_t)(offset + 2) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_write_u16_le: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    uint8_t* p = (uint8_t*)arr->data + offset;
    uint16_t v = (uint16_t)value;
    p[0] = v & 0xFF;
    p[1] = (v >> 8) & 0xFF;
}

// Read a little-endian uint16 from offset
static inline int64_t gorget_bytes_read_u16_le(const GorgetArray* arr, int64_t offset) {
    if (offset < 0 || (size_t)(offset + 2) > arr->len) {
        fprintf(stderr, "gorget: panic: bytes_read_u16_le: offset %lld out of bounds (len %zu)\n", (long long)offset, arr->len);
        exit(1);
    }
    const uint8_t* p = (const uint8_t*)arr->data + offset;
    return (int64_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

// Convert Vector[uint8] to hex string
static inline const char* gorget_bytes_to_hex(const GorgetArray* arr) {
    size_t len = arr->len;
    char* s = (char*)GORGET_ALLOC(len * 2 + 1);
    for (size_t i = 0; i < len; i++) {
        sprintf(s + i * 2, "%02x", ((uint8_t*)arr->data)[i]);
    }
    s[len * 2] = '\0';
    return s;
}

"#;

pub const REGEX_RUNTIME: &str = r#"
// ── Regex Runtime (PCRE2) ──────────────────────────────────────
#define PCRE2_CODE_UNIT_WIDTH 8
#include <pcre2.h>

// ── Regex type ──────────────────────────────────────────────────

typedef struct {
    pcre2_code* code;
    const char* pattern_str;   // strdup'd
} GorgetRegex;

// ── Match type ──────────────────────────────────────────────────

typedef struct {
    const char* text;          // strdup'd full match
    int64_t start;             // byte offset (-1 = no match sentinel)
    int64_t end_pos;           // byte offset
    const char** groups;       // array of strdup'd group strings (NULL if unmatched)
    int64_t group_count;       // capture groups (excl. group 0)
    const char** group_names;  // parallel array: name or NULL for each group
    int64_t names_len;
} GorgetRegexMatch;

// ── Thread-local error ──────────────────────────────────────────

static __thread const char* __gorget_regex_last_error = NULL;

static const char* gorget_regex_last_error(void) {
    const char* e = __gorget_regex_last_error;
    __gorget_regex_last_error = NULL;
    return e;
}

// ── Parse flags string ──────────────────────────────────────────

static uint32_t gorget_regex_parse_flags(const char* flags) {
    uint32_t opts = 0;
    if (!flags) return opts;
    for (const char* p = flags; *p; p++) {
        switch (*p) {
            case 'i': opts |= PCRE2_CASELESS; break;
            case 'm': opts |= PCRE2_MULTILINE; break;
            case 's': opts |= PCRE2_DOTALL; break;
            case 'x': opts |= PCRE2_EXTENDED; break;
            case 'u': opts |= PCRE2_UTF | PCRE2_UCP; break;
            case 'U': opts |= PCRE2_UNGREEDY; break;
            default: break;
        }
    }
    return opts;
}

// ── Compile ─────────────────────────────────────────────────────

static GorgetRegex gorget_regex_compile(const char* pattern, const char* flags) {
    GorgetRegex rx = {NULL, NULL};
    uint32_t opts = gorget_regex_parse_flags(flags);
    int errcode;
    PCRE2_SIZE erroffset;
    pcre2_code* code = pcre2_compile(
        (PCRE2_SPTR)pattern, PCRE2_ZERO_TERMINATED,
        opts, &errcode, &erroffset, NULL);
    if (!code) {
        PCRE2_UCHAR buf[256];
        pcre2_get_error_message(errcode, buf, sizeof(buf));
        char* msg = (char*)GORGET_ALLOC(512);
        snprintf(msg, 512, "regex error at offset %zu: %s", (size_t)erroffset, (char*)buf);
        __gorget_regex_last_error = msg;
        return rx;
    }
    rx.code = code;
    rx.pattern_str = strdup(pattern);
    return rx;
}

// ── Free ────────────────────────────────────────────────────────

static void gorget_regex_free(GorgetRegex* rx) {
    if (rx->code) { pcre2_code_free(rx->code); rx->code = NULL; }
    if (rx->pattern_str) { GORGET_FREE((void*)rx->pattern_str, 0); rx->pattern_str = NULL; }
}

static void gorget_regex_match_free(GorgetRegexMatch* m) {
    if (m->text) { GORGET_FREE((void*)m->text, 0); m->text = NULL; }
    if (m->groups) {
        for (int64_t i = 0; i < m->group_count; i++) {
            if (m->groups[i]) GORGET_FREE((void*)m->groups[i], 0);
        }
        GORGET_FREE(m->groups, 0);
        m->groups = NULL;
    }
    if (m->group_names) {
        for (int64_t i = 0; i < m->names_len; i++) {
            if (m->group_names[i]) GORGET_FREE((void*)m->group_names[i], 0);
        }
        GORGET_FREE(m->group_names, 0);
        m->group_names = NULL;
    }
}

// ── Drop glue (called by Gorget RAII) ───────────────────────────

static void Drop_for_Regex__drop(GorgetRegex* rx) { gorget_regex_free(rx); }
static void Drop_for_Match__drop(GorgetRegexMatch* m) { gorget_regex_match_free(m); }

// ── Helper: extract named groups array ──────────────────────────

static void gorget_regex_extract_names(pcre2_code* code, int64_t group_count,
                                        const char*** out_names, int64_t* out_names_len) {
    *out_names_len = group_count;
    if (group_count == 0) { *out_names = NULL; return; }
    const char** names = (const char**)GORGET_CALLOC(group_count, sizeof(const char*));
    uint32_t namecount;
    pcre2_pattern_info(code, PCRE2_INFO_NAMECOUNT, &namecount);
    if (namecount > 0) {
        uint32_t name_entry_size;
        PCRE2_SPTR nametable;
        pcre2_pattern_info(code, PCRE2_INFO_NAMEENTRYSIZE, &name_entry_size);
        pcre2_pattern_info(code, PCRE2_INFO_NAMETABLE, &nametable);
        for (uint32_t i = 0; i < namecount; i++) {
            PCRE2_SPTR entry = nametable + i * name_entry_size;
            int grp = (entry[0] << 8) | entry[1];
            if (grp >= 1 && grp <= group_count) {
                names[grp - 1] = strdup((const char*)(entry + 2));
            }
        }
    }
    *out_names = names;
}

// ── Find (single match) ────────────────────────────────────────

static GorgetRegexMatch gorget_regex_find(GorgetRegex* rx, const char* subject, int64_t start_offset) {
    GorgetRegexMatch m = {NULL, -1, -1, NULL, 0, NULL, 0};
    if (!rx->code) return m;
    size_t subject_len = strlen(subject);
    pcre2_match_data* md = pcre2_match_data_create_from_pattern(rx->code, NULL);
    int rc = pcre2_match(rx->code, (PCRE2_SPTR)subject, subject_len,
                         (PCRE2_SIZE)start_offset, 0, md, NULL);
    if (rc < 1) { pcre2_match_data_free(md); return m; }
    PCRE2_SIZE* ov = pcre2_get_ovector_pointer(md);
    m.start = (int64_t)ov[0];
    m.end_pos = (int64_t)ov[1];
    size_t match_len = ov[1] - ov[0];
    char* text = (char*)GORGET_ALLOC(match_len + 1);
    memcpy(text, subject + ov[0], match_len);
    text[match_len] = '\0';
    m.text = text;

    uint32_t capturecount;
    pcre2_pattern_info(rx->code, PCRE2_INFO_CAPTURECOUNT, &capturecount);
    m.group_count = (int64_t)capturecount;
    if (capturecount > 0) {
        m.groups = (const char**)GORGET_CALLOC(capturecount, sizeof(const char*));
        for (uint32_t i = 1; i <= capturecount; i++) {
            if ((int)i < rc && ov[2*i] != PCRE2_UNSET) {
                size_t glen = ov[2*i+1] - ov[2*i];
                char* g = (char*)GORGET_ALLOC(glen + 1);
                memcpy(g, subject + ov[2*i], glen);
                g[glen] = '\0';
                m.groups[i-1] = g;
            }
        }
    }
    gorget_regex_extract_names(rx->code, capturecount, &m.group_names, &m.names_len);
    pcre2_match_data_free(md);
    return m;
}

// ── find_at (alias for find with explicit offset) ────────────────
#define gorget_regex_find_at gorget_regex_find

// ── is_match ────────────────────────────────────────────────────

static bool gorget_regex_is_match(GorgetRegex* rx, const char* subject) {
    if (!rx->code) return false;
    pcre2_match_data* md = pcre2_match_data_create_from_pattern(rx->code, NULL);
    int rc = pcre2_match(rx->code, (PCRE2_SPTR)subject, strlen(subject), 0, 0, md, NULL);
    pcre2_match_data_free(md);
    return rc >= 1;
}

// ── find_all ────────────────────────────────────────────────────

static GorgetArray gorget_regex_find_all(GorgetRegex* rx, const char* subject) {
    GorgetArray arr = {NULL, 0, 0, sizeof(GorgetRegexMatch), __gorget_current_alloc};
    if (!rx->code) return arr;
    size_t subject_len = strlen(subject);
    PCRE2_SIZE offset = 0;
    while (offset <= (PCRE2_SIZE)subject_len) {
        pcre2_match_data* md = pcre2_match_data_create_from_pattern(rx->code, NULL);
        int rc = pcre2_match(rx->code, (PCRE2_SPTR)subject, subject_len, offset, 0, md, NULL);
        if (rc < 1) { pcre2_match_data_free(md); break; }
        PCRE2_SIZE* ov = pcre2_get_ovector_pointer(md);

        GorgetRegexMatch m = {NULL, -1, -1, NULL, 0, NULL, 0};
        m.start = (int64_t)ov[0];
        m.end_pos = (int64_t)ov[1];
        size_t match_len = ov[1] - ov[0];
        char* text = (char*)GORGET_ALLOC(match_len + 1);
        memcpy(text, subject + ov[0], match_len);
        text[match_len] = '\0';
        m.text = text;

        uint32_t capturecount;
        pcre2_pattern_info(rx->code, PCRE2_INFO_CAPTURECOUNT, &capturecount);
        m.group_count = (int64_t)capturecount;
        if (capturecount > 0) {
            m.groups = (const char**)GORGET_CALLOC(capturecount, sizeof(const char*));
            for (uint32_t i = 1; i <= capturecount; i++) {
                if ((int)i < rc && ov[2*i] != PCRE2_UNSET) {
                    size_t glen = ov[2*i+1] - ov[2*i];
                    char* g = (char*)GORGET_ALLOC(glen + 1);
                    memcpy(g, subject + ov[2*i], glen);
                    g[glen] = '\0';
                    m.groups[i-1] = g;
                }
            }
        }
        gorget_regex_extract_names(rx->code, capturecount, &m.group_names, &m.names_len);
        gorget_array_push(&arr, &m);
        // Save ovector values before freeing match data (ov points into md)
        PCRE2_SIZE match_start = ov[0];
        PCRE2_SIZE match_end = ov[1];
        pcre2_match_data_free(md);
        // Advance past current match; handle zero-length matches
        if (match_end == match_start) offset = match_start + 1;
        else offset = match_end;
    }
    return arr;
}

// ── Replace ─────────────────────────────────────────────────────

static GorgetString gorget_regex_replace_impl(GorgetRegex* rx, const char* subject,
                                               const char* replacement, uint32_t extra_opts) {
    GorgetString result = {NULL, 0, 0, __gorget_current_alloc};
    if (!rx->code) { result = gorget_string_new(subject); return result; }
    size_t subject_len = strlen(subject);
    size_t repl_len = strlen(replacement);
    PCRE2_SIZE outlen = 0;
    // First call to get required size
    int rc = pcre2_substitute(rx->code, (PCRE2_SPTR)subject, subject_len, 0,
                              PCRE2_SUBSTITUTE_OVERFLOW_LENGTH | extra_opts,
                              NULL, NULL,
                              (PCRE2_SPTR)replacement, repl_len,
                              NULL, &outlen);
    if (rc != PCRE2_ERROR_NOMEMORY && rc < 0) {
        // No match or error — return original
        result = gorget_string_new(subject);
        return result;
    }
    outlen += 1; // null terminator
    PCRE2_UCHAR* outbuf = (PCRE2_UCHAR*)GORGET_ALLOC(outlen);
    rc = pcre2_substitute(rx->code, (PCRE2_SPTR)subject, subject_len, 0,
                          extra_opts,
                          NULL, NULL,
                          (PCRE2_SPTR)replacement, repl_len,
                          outbuf, &outlen);
    if (rc < 0) {
        GORGET_FREE(outbuf, 0);
        result = gorget_string_new(subject);
        return result;
    }
    result.data = (char*)outbuf;
    result.len = outlen;
    result.cap = outlen + 1;
    return result;
}

static GorgetString gorget_regex_replace(GorgetRegex* rx, const char* subject, const char* replacement) {
    return gorget_regex_replace_impl(rx, subject, replacement, 0);
}

static GorgetString gorget_regex_replace_all(GorgetRegex* rx, const char* subject, const char* replacement) {
    return gorget_regex_replace_impl(rx, subject, replacement, PCRE2_SUBSTITUTE_GLOBAL);
}

// ── Split ───────────────────────────────────────────────────────

static GorgetArray gorget_regex_split(GorgetRegex* rx, const char* subject, int64_t limit) {
    GorgetArray arr = {NULL, 0, 0, sizeof(Str), __gorget_current_alloc};
    if (!rx->code || !subject) {
        const char* copy = strdup(subject ? subject : "");
        Str sv = gorget_str_from_cstr(copy);
        gorget_array_push(&arr, &sv);
        return arr;
    }
    size_t subject_len = strlen(subject);
    PCRE2_SIZE offset = 0;
    int64_t count = 0;
    while (offset <= (PCRE2_SIZE)subject_len) {
        if (limit > 0 && count >= limit - 1) break;
        pcre2_match_data* md = pcre2_match_data_create_from_pattern(rx->code, NULL);
        int rc = pcre2_match(rx->code, (PCRE2_SPTR)subject, subject_len, offset, 0, md, NULL);
        if (rc < 1) { pcre2_match_data_free(md); break; }
        PCRE2_SIZE* ov = pcre2_get_ovector_pointer(md);
        size_t seg_len = ov[0] - offset;
        char* seg = (char*)GORGET_ALLOC(seg_len + 1);
        memcpy(seg, subject + offset, seg_len);
        seg[seg_len] = '\0';
        Str sv = { .data = seg, .len = seg_len };
        gorget_array_push(&arr, &sv);
        count++;
        if (ov[1] == ov[0]) offset = ov[0] + 1;
        else offset = ov[1];
        pcre2_match_data_free(md);
    }
    // Remaining tail
    size_t tail_len = subject_len - offset;
    char* tail = (char*)GORGET_ALLOC(tail_len + 1);
    memcpy(tail, subject + offset, tail_len);
    tail[tail_len] = '\0';
    Str sv = { .data = tail, .len = tail_len };
    gorget_array_push(&arr, &sv);
    return arr;
}

// ── Fullmatch ───────────────────────────────────────────────────

static GorgetRegexMatch gorget_regex_fullmatch(GorgetRegex* rx, const char* subject) {
    GorgetRegexMatch m = gorget_regex_find(rx, subject, 0);
    if (m.start == 0 && m.end_pos == (int64_t)strlen(subject)) {
        return m;
    }
    gorget_regex_match_free(&m);
    GorgetRegexMatch empty = {NULL, -1, -1, NULL, 0, NULL, 0};
    return empty;
}

// ── Capture count ───────────────────────────────────────────────

static int64_t gorget_regex_capture_count(GorgetRegex* rx) {
    if (!rx->code) return 0;
    uint32_t count;
    pcre2_pattern_info(rx->code, PCRE2_INFO_CAPTURECOUNT, &count);
    return (int64_t)count;
}

// ── Group names ─────────────────────────────────────────────────

static GorgetArray gorget_regex_group_names(GorgetRegex* rx) {
    GorgetArray arr = {NULL, 0, 0, sizeof(Str), __gorget_current_alloc};
    if (!rx->code) return arr;
    uint32_t namecount;
    pcre2_pattern_info(rx->code, PCRE2_INFO_NAMECOUNT, &namecount);
    if (namecount == 0) return arr;
    uint32_t name_entry_size;
    PCRE2_SPTR nametable;
    pcre2_pattern_info(rx->code, PCRE2_INFO_NAMEENTRYSIZE, &name_entry_size);
    pcre2_pattern_info(rx->code, PCRE2_INFO_NAMETABLE, &nametable);
    for (uint32_t i = 0; i < namecount; i++) {
        PCRE2_SPTR entry = nametable + i * name_entry_size;
        const char* name = strdup((const char*)(entry + 2));
        Str sv = gorget_str_from_cstr(name);
        gorget_array_push(&arr, &sv);
    }
    return arr;
}

// ── Pattern string ──────────────────────────────────────────────

static const char* gorget_regex_pattern_str(GorgetRegex* rx) {
    return rx->pattern_str ? rx->pattern_str : "";
}

// ── Match accessors ─────────────────────────────────────────────

static const char* gorget_regex_match_text(GorgetRegexMatch* m) {
    return m->text ? m->text : "";
}

static int64_t gorget_regex_match_start(GorgetRegexMatch* m) { return m->start; }
static int64_t gorget_regex_match_end(GorgetRegexMatch* m) { return m->end_pos; }
static int64_t gorget_regex_match_group_count(GorgetRegexMatch* m) { return m->group_count; }

// group(n) → returns NULL if out of range or unmatched
static const char* gorget_regex_match_group(GorgetRegexMatch* m, int64_t n) {
    if (n < 0 || n >= m->group_count || !m->groups) return NULL;
    return m->groups[n];
}

// group_by_name(name) → returns NULL if not found
static const char* gorget_regex_match_group_by_name(GorgetRegexMatch* m, const char* name) {
    if (!m->group_names || !m->groups) return NULL;
    for (int64_t i = 0; i < m->names_len; i++) {
        if (m->group_names[i] && strcmp(m->group_names[i], name) == 0) {
            if (i < m->group_count) return m->groups[i];
        }
    }
    return NULL;
}

// groups() → Vector[str] of all group values
static GorgetArray gorget_regex_match_groups(GorgetRegexMatch* m) {
    GorgetArray arr = {NULL, 0, 0, sizeof(Str), __gorget_current_alloc};
    if (!m->groups) return arr;
    for (int64_t i = 0; i < m->group_count; i++) {
        const char* g = m->groups[i] ? m->groups[i] : "";
        const char* copy = strdup(g);
        Str sv = gorget_str_from_cstr(copy);
        gorget_array_push(&arr, &sv);
    }
    return arr;
}

// ── Escape ──────────────────────────────────────────────────────

static GorgetString gorget_regex_escape(const char* s) {
    if (!s) return gorget_string_new("");
    size_t len = strlen(s);
    // Worst case: every char needs escaping → 2x + 1
    char* buf = (char*)GORGET_ALLOC(len * 2 + 1);
    size_t j = 0;
    for (size_t i = 0; i < len; i++) {
        char c = s[i];
        // PCRE2 metacharacters that need escaping
        if (c == '\\' || c == '^' || c == '$' || c == '.' || c == '[' || c == ']' ||
            c == '|' || c == '(' || c == ')' || c == '?' || c == '*' || c == '+' ||
            c == '{' || c == '}' || c == '-') {
            buf[j++] = '\\';
        }
        buf[j++] = c;
    }
    buf[j] = '\0';
    GorgetString result;
    result.data = buf;
    result.len = j;
    result.cap = len * 2 + 1;
    result.alloc = __gorget_current_alloc;
    return result;
}

"#;

pub const HOT_RELOAD_RUNTIME: &str = r#"
// ── Hot Reload Runtime ──────────────────────────────────────────
#include <dlfcn.h>
#include <sys/stat.h>

#ifdef __APPLE__
#include <sys/event.h>
#include <fcntl.h>
#define GORGET_DYLIB_EXT ".dylib"
#else
#define GORGET_DYLIB_EXT ".so"
#endif

typedef struct {
    void* handle;
    void* init;
    void* tick;
    void* reload;
    uint64_t state_hash;
} GorgetGuestModule;

static GorgetGuestModule gorget_hot_load(const char* path) {
    GorgetGuestModule m = {0};
    m.handle = dlopen(path, RTLD_NOW | RTLD_LOCAL);
    if (!m.handle) {
        fprintf(stderr, "[hot-reload] dlopen failed: %s\n", dlerror());
        return m;
    }
    m.init = dlsym(m.handle, "gorget_guest_init");
    m.tick = dlsym(m.handle, "gorget_guest_tick");
    m.reload = dlsym(m.handle, "gorget_guest_reload");
    uint64_t* hash_ptr = (uint64_t*)dlsym(m.handle, "GORGET_STATE_HASH");
    m.state_hash = hash_ptr ? *hash_ptr : 0;
    return m;
}

static void gorget_hot_unload(GorgetGuestModule* m) {
    if (m->handle) {
        dlclose(m->handle);
        m->handle = NULL;
    }
}

// ── File watcher (kqueue on macOS) ──────────────────────────────
#ifdef __APPLE__

typedef struct {
    int kq;
    int* fds;
    int fd_count;
} GorgetFileWatcher;

static GorgetFileWatcher gorget_hot_watch_init(const char** paths, int count) {
    GorgetFileWatcher w = {0};
    w.kq = kqueue();
    if (w.kq < 0) {
        fprintf(stderr, "[hot-reload] kqueue() failed\n");
        return w;
    }
    w.fds = (int*)GORGET_ALLOC(sizeof(int) * count);
    w.fd_count = 0;
    for (int i = 0; i < count; i++) {
        int fd = open(paths[i], O_EVTONLY);
        if (fd < 0) {
            fprintf(stderr, "[hot-reload] Cannot watch '%s'\n", paths[i]);
            continue;
        }
        struct kevent ev;
        EV_SET(&ev, fd, EVFILT_VNODE, EV_ADD | EV_CLEAR,
               NOTE_WRITE | NOTE_RENAME | NOTE_DELETE, 0, NULL);
        kevent(w.kq, &ev, 1, NULL, 0, NULL);
        w.fds[w.fd_count++] = fd;
    }
    return w;
}

static bool gorget_hot_watch_check(GorgetFileWatcher* w) {
    struct kevent ev;
    struct timespec ts = {0, 0};  // non-blocking
    int n = kevent(w->kq, NULL, 0, &ev, 1, &ts);
    return n > 0;
}

static void gorget_hot_watch_close(GorgetFileWatcher* w) {
    for (int i = 0; i < w->fd_count; i++) {
        close(w->fds[i]);
    }
    GORGET_FREE(w->fds, 0);
    close(w->kq);
}

#else
// Linux — inotify-based watcher
#include <sys/inotify.h>
#include <unistd.h>
#include <poll.h>

typedef struct {
    int ifd;       // inotify file descriptor
    int* wds;      // array of watch descriptors
    int wd_count;  // number of watches
} GorgetFileWatcher;

static GorgetFileWatcher gorget_hot_watch_init(const char** paths, int count) {
    GorgetFileWatcher w = {0};
    w.ifd = inotify_init1(IN_NONBLOCK);
    if (w.ifd < 0) {
        fprintf(stderr, "[hot-reload] inotify_init1() failed\n");
        return w;
    }
    w.wds = (int*)GORGET_ALLOC(sizeof(int) * count);
    w.wd_count = 0;
    for (int i = 0; i < count; i++) {
        int wd = inotify_add_watch(w.ifd, paths[i],
                                   IN_MODIFY | IN_MOVE_SELF | IN_DELETE_SELF);
        if (wd < 0) {
            fprintf(stderr, "[hot-reload] Cannot watch '%s'\n", paths[i]);
            continue;
        }
        w.wds[w.wd_count++] = wd;
    }
    return w;
}

static bool gorget_hot_watch_check(GorgetFileWatcher* w) {
    char buf[4096] __attribute__((aligned(__alignof__(struct inotify_event))));
    ssize_t len = read(w->ifd, buf, sizeof(buf));
    return len > 0;
}

static void gorget_hot_watch_close(GorgetFileWatcher* w) {
    for (int i = 0; i < w->wd_count; i++) {
        inotify_rm_watch(w->ifd, w->wds[i]);
    }
    GORGET_FREE(w->wds, 0);
    close(w->ifd);
}
#endif

"#;

/// std.sync — AtomicInt, AtomicBool, Barrier, RWLock[T] + ReadGuard[T]/WriteGuard[T].
pub const SYNC_RUNTIME: &str = r#"
// ── std.sync runtime ──────────────────────────────────────────
#include <pthread.h>

// ── AtomicInt ──
typedef struct { volatile int64_t __val; } GorgetAtomicInt;

static inline GorgetAtomicInt* gorget_atomic_int_new(int64_t v) {
    GorgetAtomicInt* a = (GorgetAtomicInt*)GORGET_ALLOC(sizeof(GorgetAtomicInt));
    __atomic_store_n(&a->__val, v, __ATOMIC_SEQ_CST);
    return a;
}
static inline int64_t gorget_atomic_int_load(GorgetAtomicInt* a) {
    return __atomic_load_n(&a->__val, __ATOMIC_SEQ_CST);
}
static inline void gorget_atomic_int_store(GorgetAtomicInt* a, int64_t v) {
    __atomic_store_n(&a->__val, v, __ATOMIC_SEQ_CST);
}
static inline int64_t gorget_atomic_int_add(GorgetAtomicInt* a, int64_t v) {
    return __atomic_fetch_add(&a->__val, v, __ATOMIC_SEQ_CST);
}
static inline int64_t gorget_atomic_int_sub(GorgetAtomicInt* a, int64_t v) {
    return __atomic_fetch_sub(&a->__val, v, __ATOMIC_SEQ_CST);
}
static inline int gorget_atomic_int_compare_exchange(GorgetAtomicInt* a, int64_t expected, int64_t desired) {
    return __atomic_compare_exchange_n(&a->__val, &expected, desired, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
}

// ── AtomicBool ──
typedef struct { volatile int __val; } GorgetAtomicBool;

static inline GorgetAtomicBool* gorget_atomic_bool_new(int v) {
    GorgetAtomicBool* a = (GorgetAtomicBool*)GORGET_ALLOC(sizeof(GorgetAtomicBool));
    __atomic_store_n(&a->__val, v ? 1 : 0, __ATOMIC_SEQ_CST);
    return a;
}
static inline int gorget_atomic_bool_load(GorgetAtomicBool* a) {
    return __atomic_load_n(&a->__val, __ATOMIC_SEQ_CST);
}
static inline void gorget_atomic_bool_store(GorgetAtomicBool* a, int v) {
    __atomic_store_n(&a->__val, v ? 1 : 0, __ATOMIC_SEQ_CST);
}
static inline int gorget_atomic_bool_swap(GorgetAtomicBool* a, int v) {
    return __atomic_exchange_n(&a->__val, v ? 1 : 0, __ATOMIC_SEQ_CST);
}
static inline int gorget_atomic_bool_compare_exchange(GorgetAtomicBool* a, int expected, int desired) {
    int e = expected ? 1 : 0;
    return __atomic_compare_exchange_n(&a->__val, &e, desired ? 1 : 0, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
}

// ── Barrier ──
// Portable implementation using mutex+condvar+generation counter.
typedef struct {
    pthread_mutex_t mtx;
    pthread_cond_t  cond;
    int             count;       // total threads required
    int             arrived;     // arrived this generation
    int             generation;  // increments each cycle
} GorgetBarrier;

static inline GorgetBarrier* gorget_barrier_new(int64_t n) {
    GorgetBarrier* b = (GorgetBarrier*)GORGET_CALLOC(1, sizeof(GorgetBarrier));
    pthread_mutex_init(&b->mtx, NULL);
    pthread_cond_init(&b->cond, NULL);
    b->count = (int)n;
    return b;
}
static inline void gorget_barrier_wait(GorgetBarrier* b) {
    int gen;
    pthread_mutex_lock(&b->mtx);
    gen = b->generation;
    b->arrived++;
    if (b->arrived == b->count) {
        b->arrived = 0;
        b->generation++;
        pthread_cond_broadcast(&b->cond);
    } else {
        while (gen == b->generation)
            pthread_cond_wait(&b->cond, &b->mtx);
    }
    pthread_mutex_unlock(&b->mtx);
}

// ── RWLock[T] + ReadGuard[T] + WriteGuard[T] ──
typedef struct GorgetRWLock {
    pthread_rwlock_t lock;
    void*            data;
    size_t           data_size;
} GorgetRWLock;

typedef struct { GorgetRWLock* rwlock; void* ptr; } gorget_read_guard_t;
typedef struct { GorgetRWLock* rwlock; void* ptr; } gorget_write_guard_t;

static inline GorgetRWLock* gorget_rwlock_new(size_t size, void* init_data) {
    GorgetRWLock* rw = (GorgetRWLock*)GORGET_ALLOC(sizeof(GorgetRWLock));
    pthread_rwlock_init(&rw->lock, NULL);
    rw->data = GORGET_ALLOC(size);
    rw->data_size = size;
    memcpy(rw->data, init_data, size);
    return rw;
}
static inline gorget_read_guard_t gorget_rwlock_read(GorgetRWLock* rw) {
    pthread_rwlock_rdlock(&rw->lock);
    gorget_read_guard_t g;
    g.rwlock = rw;
    g.ptr    = rw->data;
    return g;
}
static inline gorget_write_guard_t gorget_rwlock_write(GorgetRWLock* rw) {
    pthread_rwlock_wrlock(&rw->lock);
    gorget_write_guard_t g;
    g.rwlock = rw;
    g.ptr    = rw->data;
    return g;
}
static inline void gorget_read_guard_release(gorget_read_guard_t* g) {
    if (!g->rwlock) return;
    pthread_rwlock_unlock(&g->rwlock->lock);
    g->rwlock = NULL; g->ptr = NULL;
}
static inline void gorget_write_guard_release(gorget_write_guard_t* g) {
    if (!g->rwlock) return;
    pthread_rwlock_unlock(&g->rwlock->lock);
    g->rwlock = NULL; g->ptr = NULL;
}

// ── CondVar ──
typedef struct { pthread_cond_t cond; } GorgetCondVar;

static inline GorgetCondVar* gorget_condvar_new(void) {
    GorgetCondVar* cv = (GorgetCondVar*)GORGET_CALLOC(1, sizeof(GorgetCondVar));
    pthread_cond_init(&cv->cond, NULL);
    return cv;
}
static inline void gorget_condvar_notify_one(GorgetCondVar* cv) {
    pthread_cond_signal(&cv->cond);
}
static inline void gorget_condvar_notify_all(GorgetCondVar* cv) {
    pthread_cond_broadcast(&cv->cond);
}
"#;

/// std.thread — Thread[T], thread_spawn, current_thread_id.
/// Per-function spawn/join C helpers are emitted by emit_thread_helpers() in the backend.
pub const THREAD_RUNTIME: &str = r#"
// ── std.thread runtime ──────────────────────────────────────
#include <pthread.h>

static inline int64_t gorget_current_thread_id(void) {
    return (int64_t)(uintptr_t)pthread_self();
}
"#;

/// Enhanced std.process runtime — adds Process type with fork+exec+pipes.
pub const PROCESS_SPAWN_RUNTIME: &str = r#"
// ── std.process: Process type (fork+exec+pipes) ──────────────
#include <signal.h>
#include <fcntl.h>

typedef struct GorgetProcess {
    pid_t pid;
    int   stdin_fd;   // parent write end  (-1 if not used)
    int   stdout_fd;  // parent read end   (-1 if not used)
    int   stderr_fd;  // parent read end   (-1 if not used)
} GorgetProcess;

// Spawn a child process with stdin/stdout/stderr pipes.
// Returns a Result[Process, str]:
//   Ok  → packed as GorgetProcess* (non-NULL)
//   Err → packed as NULL (caller reads gorget_process_spawn_err() for message)
static _Thread_local char __gorget_spawn_errbuf[256];

static inline GorgetProcess* gorget_process_spawn(const char* program, GorgetArray* args) {
    __gorget_spawn_errbuf[0] = '\0'; // clear stale error
    int in_pipe[2], out_pipe[2], err_pipe[2];
    if (pipe(in_pipe)  < 0 ||
        pipe(out_pipe) < 0 ||
        pipe(err_pipe) < 0) {
        snprintf(__gorget_spawn_errbuf, sizeof(__gorget_spawn_errbuf),
                 "pipe: %s", strerror(errno));
        return NULL;
    }

    // Build argv: program + elements from args vector
    int argc = args ? (int)args->len : 0;
    char** argv = (char**)GORGET_ALLOC(sizeof(char*) * (size_t)(argc + 2));
    argv[0] = (char*)program;
    for (int i = 0; i < argc; i++) {
        Str* sv = (Str*)gorget_array_get(args, i);
        char* s = (char*)GORGET_ALLOC(sv->len + 1);
        memcpy(s, sv->data, sv->len);
        s[sv->len] = '\0';
        argv[i + 1] = s;
    }
    argv[argc + 1] = NULL;

    pid_t pid = fork();
    if (pid < 0) {
        snprintf(__gorget_spawn_errbuf, sizeof(__gorget_spawn_errbuf),
                 "fork: %s", strerror(errno));
        close(in_pipe[0]); close(in_pipe[1]);
        close(out_pipe[0]); close(out_pipe[1]);
        close(err_pipe[0]); close(err_pipe[1]);
        GORGET_FREE(argv, 0);
        return NULL;
    }
    if (pid == 0) {
        // Child: wire pipes then exec
        dup2(in_pipe[0],  STDIN_FILENO);
        dup2(out_pipe[1], STDOUT_FILENO);
        dup2(err_pipe[1], STDERR_FILENO);
        close(in_pipe[0]); close(in_pipe[1]);
        close(out_pipe[0]); close(out_pipe[1]);
        close(err_pipe[0]); close(err_pipe[1]);
        execvp(argv[0], argv);
        _exit(127);
    }
    // Parent: close child-side fds
    close(in_pipe[0]);
    close(out_pipe[1]);
    close(err_pipe[1]);

    GorgetProcess* proc = (GorgetProcess*)GORGET_ALLOC(sizeof(GorgetProcess));
    proc->pid       = pid;
    proc->stdin_fd  = in_pipe[1];
    proc->stdout_fd = out_pipe[0];
    proc->stderr_fd = err_pipe[0];
    GORGET_FREE(argv, 0);
    return proc;
}

static inline const char* gorget_process_spawn_err(void) {
    return __gorget_spawn_errbuf[0] ? __gorget_spawn_errbuf : NULL;
}

static inline int64_t gorget_process_wait(GorgetProcess* proc) {
    int status = 0;
    waitpid(proc->pid, &status, 0);
    return WIFEXITED(status) ? (int64_t)WEXITSTATUS(status) : (int64_t)-1;
}

static inline void gorget_process_kill(GorgetProcess* proc) {
    kill(proc->pid, SIGTERM);
}

static inline int64_t gorget_process_pid(GorgetProcess* proc) {
    return (int64_t)proc->pid;
}

static inline void gorget_process_write_stdin(GorgetProcess* proc, Str data) {
    if (proc->stdin_fd >= 0) write(proc->stdin_fd, data.data, data.len);
}

static inline void gorget_process_close_stdin(GorgetProcess* proc) {
    if (proc->stdin_fd >= 0) { close(proc->stdin_fd); proc->stdin_fd = -1; }
}

static inline GorgetString gorget_process_read_stdout(GorgetProcess* proc) {
    if (proc->stdout_fd < 0) return gorget_string_new("");
    size_t cap = 256, len = 0;
    char* buf = (char*)GORGET_ALLOC(cap);
    ssize_t n;
    while ((n = read(proc->stdout_fd, buf + len, cap - len - 1)) > 0) {
        len += (size_t)n;
        if (len + 1 >= cap) { size_t newcap = cap * 2; buf = (char*)GORGET_REALLOC(buf, cap, newcap); cap = newcap; }
    }
    buf[len] = '\0';
    return (GorgetString){buf, len, cap, __gorget_current_alloc};
}

static inline GorgetString gorget_process_read_stderr(GorgetProcess* proc) {
    if (proc->stderr_fd < 0) return gorget_string_new("");
    size_t cap = 256, len = 0;
    char* buf = (char*)GORGET_ALLOC(cap);
    ssize_t n;
    while ((n = read(proc->stderr_fd, buf + len, cap - len - 1)) > 0) {
        len += (size_t)n;
        if (len + 1 >= cap) { size_t newcap = cap * 2; buf = (char*)GORGET_REALLOC(buf, cap, newcap); cap = newcap; }
    }
    buf[len] = '\0';
    return (GorgetString){buf, len, cap, __gorget_current_alloc};
}

static inline int64_t gorget_getpid(void) {
    return (int64_t)getpid();
}
"#;
